// Parse Ollama JSON response
const meta = $('Clean Content & Substance Gate').item.json;
const res = $input.first().json;
let synthesis = {};
try {
  synthesis = typeof res.response === 'string' ? JSON.parse(res.response) : res.response;
} catch (e) {
  synthesis = { raw: res.response, error: e.message };
}

return [{
  json: {
    ...meta,
    synthesis,
    synthesized_at: new Date().toISOString()
  }
}];

